head.script:
scwin.vScrenID = "ULDFIS00300_P7.xml";

scwin.comCd = "";   // 기업코드 
scwin.basYymm = ""; // 결산년월

scwin.onpageload = function() {

   scwin.param = $c.data.getParameter();
   scwin.comCd = scwin.param.comCd; 
   scwin.basYymm = scwin.param.basYymm; 

   scwin.fn_Search(); //조회
};

scwin.onpageunload = function() {

}; 

/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function() {
  dlt_ColtrlGrtDtl1Res.removeAll();
  dlt_ColtrlGrtDtl2Res.removeAll();
};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    return true;
};


/**
 * 담보및지급보증 상세 조회
 */
scwin.fn_Search = function() {

    //데이터셋 초기화
    scwin.fn_InitDs();

    // 조회조건 체크.
    if (!scwin.fn_ChkValid()) {
        return;
    }

    // 상단 조회
    scwin.fn_ContgntDebtDtl1();
};


/**
 * 담보및지급보증 상세 조회(상단)
 */
scwin.fn_ContgntDebtDtl1 = async function() {

    const ibxKisCd = scwin.param.comCd; 
    const acntclsDt = scwin.param.basYymm; 

    let url = "/api/listing/nice/individual-notes/collateral-guarantees/received?kisCd="+ibxKisCd+"&acntclsDt="+acntclsDt;
    $c.sbm.setAction(sbm_dlt_ColtrlGrtDtl1, url);
    await $c.sbm.execute(sbm_dlt_ColtrlGrtDtl1);

    // 상단 div그리기
    await scwin.fn_AppendContents(dlt_ColtrlGrtDtl1Res,grp_Ctnt)

    //담보및지급보증 하단 조회
    scwin.fn_ContgntDebtDtl2(); 
};


/**
 * 담보및지급보증 상세 조회(하단)
 */
scwin.fn_ContgntDebtDtl2 = async function() {
    const ibxKisCd = $p.parent().wfm_header.getWindow().ibx_KisCd.getValue();
    //입시
    //const ibxKisCd = "H61461";
    //const acntclsDt = "201912" 

    let url = "/api/listing/nice/individual-notes/collateral-guarantees/provided?kisCd="+ibxKisCd+"&acntclsDt="+acntclsDt;
    $c.sbm.setAction(sbm_dlt_ColtrlGrtDtl2, url);
    await $c.sbm.execute(sbm_dlt_ColtrlGrtDtl2);

    // 하단 div그리기
    scwin.fn_AppendContents(dlt_ColtrlGrtDtl2Res,grp_Ctnt1);

};


/**
 * 컨텐츠 append
 */
scwin.fn_AppendContents = function(pDs, pGrp) {
    let strContent = "<div style='overflow-x:hidden;width:100%;height:600px;font-family:돋움체;'>";
    for (var nRow = 0; nRow <= pDs.getRowCount(); nRow++ ) {
        strContent = strContent + pDs.getCellData(nRow, "ctnt");
    }
    console.log(strContent);
    strContent = strContent + "</div>";
    let grpCtntObj = pGrp.render;
    grpCtntObj.innerHTML = strContent;
    pGrp.setStyle("border", "1px solid blue");
    pGrp.setStyle("magin-top", "30px");

};


//팝업닫기
scwin.btn_Close_onclick = function (e) {
    $c.win.closePopup();
};
